head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pf_listinvstg.js");
scwin.vScrenID = "ULDSTF09306.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_811; //PF 변경상장
scwin.MSG_50M_LOW = '신탁원본액 50억미만에 해당됩니다.';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initItem = function() {
    $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, LIST_METHD_TP_CD_3);
    $c.stf.setObjectValue(edt_TRST_DISTR_PAY_BAS_DD, $c.ut.cGetToday("yyyymmdd").substring(0, 4) + "0101");
};
scwin.fn_calcuate = function() {
    try {
        var vsum = eval(parseInt($c.stf.getObjectValue(edt_BF_LIST_SHRS))) + eval(parseInt($c.stf.getObjectValue(edt_INCDEC_LIST_SHRS)));
        $c.stf.setObjectValue(edt_LIST_SHRS, vsum);
    } catch (err) {
        $c.win.alert("[증권수 합산처리 중  오류]");
    }
};
scwin.fn_50mcalcuate = function() {
    if (($c.stf.getObjectValue(edt_LIST_SHRS) * dts_Isu.getCellData(1, "ISU_PRC")) < 5000000000) {
        $c.win.alert(scwin.MSG_50M_LOW);
    }
};
scwin.fn_bf_read_sync = function() {
    var url = "/pf/PfLstinvstg.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_PF_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_recv_read_sync = function(row) {
    var url = "/pf/PfLstinvstg.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_PF_RECV + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ACPT_NO=" + scwin.vAcptNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
    scwin.fn_initItem();
};
scwin.fn_read_sync = function() {
    var url = "/pf/PfLstinvstg.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_PF_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BENFCERT_ESTBREPUR_DD) == "") {
        $c.win.alert("[설정및환매일]을 입력하세요.");
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INCDEC_LIST_SHRS) == "") {
        $c.win.alert("[증감증권수]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }
    if (!scwin.fn_checkNumber(edt_INCDEC_LIST_SHRS, '증감증권수')) return false;
    if ($c.stf.getObjectValue(edt_LIST_SHRS) == "") {
        $c.win.alert("[변경후 상장증권수]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if (!scwin.fn_checkNumber(edt_LIST_SHRS, '변경후 상장증권수')) return false;
    if ($c.stf.getObjectValue(cmb_ISU_RSN_CONTN) == "") {
        $c.win.alert("[변경사유]를 입력하세요.");
        cmb_ISU_RSN_CONTN.focus();
        return false;
    }

    // fn_50mcalcuate(); jackal_11.05.12

    if ($c.stf.getObjectValue(edt_TRST_DISTR_PAY_BAS_DD) == "") {
        $c.win.alert("[분배지급기준일]을 입력하세요.");
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_REMK).length > 500) {
        $c.win.alert("[기타]항목이 입력사이즈를 초과하였씁니다.");
        txa_REMK.focus();
        return false;
    }
    return true;
};
scwin.fn_checkNumber = function(obj, str) {
    if ($c.stf.getObjectValue(obj) == 0) {
        $c.win.alert("[" + str + "]를 '" + $c.stf.getObjectValue(obj) + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lcp.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            //dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lcp.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!fn_check_delete_discls_procsstat(dts_DELETE, dts_Isu.getCellData(1, "BZ_PROCS_NO"))) return;
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    //alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    //dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;
    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "ISU_CD", $c.stf.getObjectValue(txb_ISU_CD));
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd);
    //alert('[dts_Isu]'+dts_Isu.text);

    trs_Save.Action = $c.lcp.fn_encodeNSession("/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveIsuIssChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",ACPT_NO=" + scwin.vAcptNo + ",BYACPTNO_SEQ=1" + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_CHG_ISS_PF_HIST;
    trs_Save.Post();
};
scwin.fn_RecvtIsuDel = function() {
    if (scwin.vAcptNo == "") {
        $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    scwin.TR_JOB = 'D';
    if (!window.confirm($c.stf.getMessageParam('MSG-A006', "신청종목삭제"))) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
        trs_Save.Action = $c.lc.fn_encodeNSession("/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveIsuIssChgList");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
        trs_Save.Parameters = "TRS_IDX=" + TRS_IDX_DELETE2 + ",ACPT_NO=" + scwin.vAcptNo + ",BYACPTNO_SEQ=1" + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_LIST_APPL_FORM_DEL;
        trs_Save.Post();
    }
};
scwin.fn_dscl = async function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("공시안내문 생성 처리할 대상자료가 선택되지 않았거나, 없습니다.");
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68155A";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = js_market;
        arr[4] = '';
        arr[5] = '';
        $c.stf.CopyDataSet(dts_Isu, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", txb_ISU_CD.getValue());
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_all_list_sync;
    fr_fn_list_sync();
};
scwin.dts_DELETE_OnLoadError = function() {
    $c.stf.alert_error(dts_DELETE);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_RecvIsuDel_onclick = function() {
    scwin.fn_RecvtIsuDel();
};
scwin.edt_INCDEC_LIST_SHRS_OnKillFocus = function() {
    scwin.fn_calcuate();
};
scwin.img_BENFCERT_ESTBREPUR_DD_onclick = function() {
    popUpCalendar2(edt_BENFCERT_ESTBREPUR_DD);
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.img_TRST_DISTR_PAY_BAS_DD_onclick = function() {
    popUpCalendar2(edt_TRST_DISTR_PAY_BAS_DD);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R" && scwin.vBzProcsNo == '')) {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_LIST_DD, false);
        $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
    }

    /*
    	if (vOpenTyp == "R" && vBzProcsNo == "") {
    		btn_RecvIsuDel.src = "../img/btn_RcvdocDel.gif";
    		btn_RecvIsuDel.disabled = false;
    	} else {
    		btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
    		btn_RecvIsuDel.disabled = true;
    	}
    */
};
scwin.trs_Save_OnFail = function() {
    $c.lcp.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lcp.fn_alertMsg('S');
    scwin.fn_parentRefresh(); // 목록 다시 조회
    if (scwin.TR_JOB == 'D') {
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
        buttonSet.setUpdateStatus();
    }
};
scwin.gform_onload = function() {
    btn_RecvIsuDel.style.visibility = "hidden";
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vAcptNo = parentWin.scwin.vAcptNo;
    scwin.vIsurCd = parentWin.scwin.vIsurCd;
    scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
    $c.stf.setObjectValue(txb_ISU_CD, $c.stf.getObjectValue(parentWin.txb_ISU_CD));
    $c.stf.setObjectValue(txb_ISU_NM, $c.stf.getObjectValue(parentWin.txb_ISU_NM));
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성s
    //buttonSet.setDrftInfo( btn_Drft, fn_drft );			// 기안

    if (scwin.vOpenTyp == "R") {
        scwin.fn_recv_read_sync();
    } else if (scwin.vOpenTyp == "H") {
        scwin.fn_read_sync();
    } else if (scwin.vOpenTyp == "N") {
        scwin.fn_bf_read_sync();
        scwin.fn_initItem();
    }
};
